INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist eine Escape-Sequenz dasselbe wie ein normales Zeichen?', 2, '[{"text": "Nein", "correct": true, "because": "Steuerzeichen darstellen"}, {"text": "Ja", "correct": false, "because": "Spezielle Funktion"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Hauptfunktion hat eine Escape-Sequenz?', 3, '[{"text": "Steuerzeichen einfügen", "correct": true, "because": "Formatierung"}, {"text": "Daten speichern", "correct": false, "because": "Nicht Speicher"}, {"text": "Code ausführen", "correct": false, "because": "Nur Darstellung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Beispiele sind Escape-Sequenzen?', 5, '[{"text": "\\n", "correct": true, "because": "Zeilenumbruch"}, {"text": "\\t", "correct": true, "because": "Tabulator"}, {"text": "abc", "correct": false, "because": "Normale Zeichen"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Escape-Sequenzen beginnen mit einem Backslash. b) Sie sind nur für Textdateien.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Breitere Nutzung"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei Escape-Sequenzen?', 4, '[{"text": "Syntax", "correct": false, "because": "Korrektheit nötig"}, {"text": "Programmiersprache", "correct": false, "because": "Abhängig davon"}, {"text": "Papierformat", "correct": true, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Escape-Sequenzen nur in Strings vorkommen?', 2, '[{"text": "Ja", "correct": true, "because": "Textdarstellung"}, {"text": "Nein", "correct": false, "because": "Hauptsächlich Strings"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Escape-Sequenz erzeugt einen Zeilenumbruch?', 3, '[{"text": "\\n", "correct": true, "because": "New Line"}, {"text": "\\t", "correct": false, "because": "Tabulator"}, {"text": "\\r", "correct": false, "because": "Carriage Return"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Programmiersprachen nutzen Escape-Sequenzen?', 5, '[{"text": "C", "correct": true, "because": "Z. B. \\n"}, {"text": "Python", "correct": true, "because": "Z. B. \\t"}, {"text": "HTML", "correct": false, "because": "Keine Sequenzen"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Escape-Sequenzen steuern die Ausgabe. b) Sie sind nur für Drucker. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Breitere Nutzung"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für Escape-Sequenzen?', 4, '[{"text": "Backslash", "correct": false, "because": "Startzeichen"}, {"text": "Programmiersprache", "correct": false, "because": "Kontext nötig"}, {"text": "Physische Tastatur", "correct": true, "because": "Code genügt"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Sind Escape-Sequenzen nur für Konsolenausgabe?', 2, '[{"text": "Nein", "correct": true, "because": "Auch Dateien"}, {"text": "Ja", "correct": false, "because": "Breitere Nutzung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Escape-Sequenzen sind häufig?', 4, '[{"text": "\\b", "correct": true, "because": "Backspace"}, {"text": "\\r", "correct": true, "because": "Carriage Return"}, {"text": "\\z", "correct": false, "because": "Nicht üblich"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Escape-Sequenzen nur in alten Sprachen genutzt werden. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Auch moderne Sprachen"}, {"text": "Ja", "correct": false, "because": "Breit anwendbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei Escape-Sequenzen?', 3, '[{"text": "Korrekte Syntax", "correct": true, "because": "Funktion sicherstellen"}, {"text": "Farben", "correct": false, "because": "Irrelevant"}, {"text": "Schnelligkeit", "correct": false, "because": "Korrektheit zählt"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Escape-Sequenzen ändern die Ausgabe. b) Sie sind nur für Zahlen.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Textformatierung"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Probleme können Escape-Sequenzen verursachen?', 5, '[{"text": "Syntaxfehler", "correct": true, "because": "Falsche Eingabe"}, {"text": "Ausgabeprobleme", "correct": true, "because": "Fehlinterpretation"}, {"text": "Papierstau", "correct": false, "because": "Nicht physisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei Escape-Sequenzen unwichtig?', 3, '[{"text": "Backslash", "correct": false, "because": "Startzeichen"}, {"text": "Steuerzeichen", "correct": false, "because": "Funktion"}, {"text": "Papiergröße", "correct": true, "because": "Kein Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Werden Escape-Sequenzen nur in Strings genutzt?', 3, '[{"text": "Ja", "correct": true, "because": "Textkontext"}, {"text": "Nein", "correct": false, "because": "Hauptsächlich Strings"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Escape-Sequenzen plattformabhängig sind?', 2, '[{"text": "Ja", "correct": true, "because": "Z. B. \\r\\n vs. \\n"}, {"text": "Nein", "correct": false, "because": "Unterschiede existieren"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Element ist für Escape-Sequenzen zentral?', 4, '[{"text": "Backslash", "correct": true, "because": "Start der Sequenz"}, {"text": "Papierformat", "correct": false, "because": "Irrelevant"}, {"text": "Manuelle Eingabe", "correct": false, "because": "Code genügt"}]');
